export function getFailureScenario(id: string) {
  return FAILURE_SCENARIOS.find((failure) => failure.id === id);
}

export function getMeridianDiagnosticPreset(id: string | undefined) {
  return MERIDIAN_DIAGNOSTIC_PRESETS.find((preset) => preset.id === id);
}

function scenario(input: ScenarioInput): FailureScenario {
  const owner = input.owner ?? "Customer voice platform team";
  return {
    id: input.id,
    title: input.title,
    category: input.category,
    description: input.description,
    likelySymptoms: input.symptoms,
    affectedNodeTypes: input.nodes,
    affectedConnectionFlows: input.flows,
    possibleRootCauses: input.causes,
    diagnosticChecks: input.checks,
    mitigationOptions: [
      {
        id: `${input.id}-contain`,
        action: input.containment,
        expectedBenefit: "Reduces immediate customer impact while preserving evidence.",
        tradeoff: "May reduce automation or add a handoff while the cause remains unconfirmed.",
        implementationOwner: owner,
        complexity: "Small",
        horizon: "immediate-containment",
        validationStep: input.validation,
        architectureChangesRequired: ["Update the affected boundary state and fallback policy."],
      },
      {
        id: `${input.id}-correct`,
        action: input.correction,
        expectedBenefit: "Addresses the likely system cause and makes recurrence measurable.",
        tradeoff: "Requires representative evidence, controlled rollout, and operational ownership.",
        implementationOwner: owner,
        complexity: input.severity === "critical" ? "Large" : "Medium",
        horizon: "long-term-correction",
        validationStep: input.validation,
        architectureChangesRequired: ["Update configuration or topology only after the diagnostic hypothesis is supported.", "Record the validation checkpoint in observability."],
      },
    ],
    fallbackBehavior: input.fallback ?? "Use a bounded retry only when safe, then preserve context for a human-agent or explicitly unavailable path.",
    customerFacingImpact: input.customerImpact ?? input.symptoms[0],
    metricsToInspect: input.metrics,
    validationTest: input.validation,
    severity: input.severity ?? "medium",
    confidence: input.confidence ?? "moderate",
    canCascade: Boolean(input.cascade?.length),
    cascadeNodeTypes: input.cascade ?? [],
  };
}
